% Solver generated by SolverMapp
clear; clc;

%% Stage 0: Inputs and start values of state variables
G          = 1; % [Input] (m^3/(kg s^2)) Gravitational constant (normalised)
N          = 3; % [Input] (1) Number of bodies
v          = [0.466203685, 0.43236573; 0.466203685, 0.43236573; -0.93240737, -0.86473146]; % [State] (m/s) Velocities, one row per body
r          = [0.97000436, -0.24308753; -0.97000436, 0.24308753; 0, 0]; % [State] (m) Positions, one row per body
m          = 1 * ones(N, 1); % [Input] (kg) Masses

%% Stage 1
% --- ODE system: r, v over t: RK4, 2000 steps ---
% Positions: \frac{d\mathbf{r}_i}{dt} = \mathbf{v}_i
% Velocities: \frac{d\mathbf{v}_i}{dt} = \sum_{j \ne i} G m_j \frac{\mathbf{r}_j - \mathbf{r}_i}{\|\mathbf{r}_j - \mathbf{r}_i\|^3}
t = 0;
h_rk = (6.32591398 - t) / 2000;
% Solution every 10 steps -> ode_system_1.csv
fid_ode1 = fopen('ode_system_1.csv', 'w');
head_ode = 't';
head_ode = [head_ode, sprintf(',r[%d]', 1:numel(r))];
head_ode = [head_ode, sprintf(',v[%d]', 1:numel(v))];
fprintf(fid_ode1, '%s\n', head_ode);
row_ode = [t, reshape(r.', 1, []), reshape(v.', 1, [])];
fprintf(fid_ode1, [repmat('%.17g,', 1, numel(row_ode) - 1), '%.17g\n'], row_ode);
w_rk = [1, 2, 2, 1]; c_rk = [0.5, 0.5, 1];
for step = 1:2000
    t_rk0 = t;
    r_rk0 = r; r_acc = 0;
    v_rk0 = v; v_acc = 0;
    for stage = 1:4
        r_rate = zeros(size(r));
        for i = 1:N
            r_rate(i, :) = (v(i, :).').';
        end
        v_rate = zeros(size(v));
        for i = 1:N
            s_sum1 = 0;
            for j = 1:N
                if j ~= i
                    s_sum1 = s_sum1 + (G * m(j) * ((r(j, :).' - r(i, :).') / norm(r(j, :).' - r(i, :).')^3));
                end
            end
            v_rate(i, :) = (s_sum1).';
        end
        r_acc = r_acc + w_rk(stage) * r_rate;
        v_acc = v_acc + w_rk(stage) * v_rate;
        if stage < 4
            t = t_rk0 + c_rk(stage) * h_rk;
            r = r_rk0 + c_rk(stage) * h_rk * r_rate;
            v = v_rk0 + c_rk(stage) * h_rk * v_rate;
        end
    end
    t = t_rk0 + h_rk;
    r = r_rk0 + h_rk / 6 * r_acc;
    v = v_rk0 + h_rk / 6 * v_acc;
    if mod(step, 10) == 0
        row_ode = [t, reshape(r.', 1, []), reshape(v.', 1, [])];
        fprintf(fid_ode1, [repmat('%.17g,', 1, numel(row_ode) - 1), '%.17g\n'], row_ode);
    end
end
fclose(fid_ode1);

%% Stage 2
% [EXPLICIT] Total energy: E = \sum_i \frac{1}{2} m_i \|\mathbf{v}_i\|^2 - \sum_{i<j} \frac{G m_i m_j}{\|\mathbf{r}_i - \mathbf{r}_j\|}
s_sum2 = 0;
for i = 1:N
    s_sum2 = s_sum2 + (1 / 2 * m(i) * norm(v(i, :).')^2);
end
s_sum3 = 0;
for i = 1:N
    s_sum4 = 0;
    for j = 1:N
        if i < j
            s_sum4 = s_sum4 + (G * m(i) * m(j) / norm(r(i, :).' - r(j, :).'));
        end
    end
    s_sum3 = s_sum3 + (s_sum4);
end
E = s_sum2 - s_sum3;

%% Results
fprintf('%-12s = %s\n', 'v', mat2str(v));
fprintf('%-12s = %s\n', 't', mat2str(t));
fprintf('%-12s = %s\n', 'r', mat2str(r));
fprintf('%-12s = %s\n', 'G', mat2str(G));
fprintf('%-12s = %s\n', 'm', mat2str(m));
fprintf('%-12s = %s\n', 'E', mat2str(E));
fprintf('%-12s = %s\n', 'N', mat2str(N));